param([switch]$PrepareMetadata, [string]$VerifiedSourceSnapshot = '')
$ErrorActionPreference = 'Stop'
$project = Split-Path $PSScriptRoot -Parent
$formalRoot = Split-Path $project -Parent
. (Join-Path $PSScriptRoot 'local-modules.ps1')
if ($PrepareMetadata -and $VerifiedSourceSnapshot) { throw 'PrepareMetadata cannot publish a verified snapshot.' }
$inventory = @(Get-Content -Raw -Encoding utf8 -LiteralPath (Join-Path $project 'source-inventory.json') | ConvertFrom-Json)
$rows = [System.Collections.Generic.List[object]]::new()
function AddRecord([string]$id, [string[]]$declarations, [string]$proof, [string]$math, [string]$notes) {
    $source = $inventory | Where-Object id -eq $id
    if (!$source) { throw "Unknown source id: $id" }
    $rows.Add([ordered]@{
        id=$id; number=$source.number; source=$source.file; line=$source.line;
        original_statement=$source.statement_latex; ordinary_mathematics=$math;
        lean_declarations=$declarations; statement_status='checked against source';
        proof_status=$proof; method_status='aligned, with documented formal expansions';
        correspondence_notes=$notes; verification='verification/axiom-and-statement-audit.txt'
    })
}
AddRecord 'prop:iso-invariance' @('PFP.Proposition_2_5','PFP.proposition_2_5','ThesisCommon.HasCPFP.of_equiv_exact') 'complete' `
    'Conjugate T by S, apply C-PFP in F, and conjugate both factors back. Each conjugation costs the distortion of S; their product gives C ||S||^2 ||S^-1||^2.' `
    'Original Banach hypotheses are weakened to normed spaces. Every real bound C is allowed in the stronger lemma, so in particular the source C>=1. The constant is exact. Zero spaces are included.'
