AddRecord 'lem:block-decomp3' @('PFP.Lemma_4_30_asPrinted','PFP.Lemma_4_30','PFP.lemma_4_30_uncountable','ThesisCommon.hasCountableTotalDual_of_separable','ThesisCommon.UncountableSchauderSum.diagonal_coordinates_of_two_sided_countable','ThesisCommon.UncountableSchauderSum.diagonal_coordinates_of_separable') 'context-restored uncountable version complete; unrestricted printed formula not proved' `
