    @{id='GM.WIENER.QUOTIENT.CONDITIONAL'; math='Actual seminorm-ideal quotient has an isometric multiplicative Wiener identification conditional on finite-spread approximation'; lean='ThesisCommon.GowersMaurey.wienerQuotientIsometryEquiv'; depends=@('GM.SPREAD.REDUCTION','GM.KERNEL.SS','ThesisCommon.GowersMaurey.wienerRepresentative_comp'); remaining_inputs=@('Every actual operator is finite-spread approximable')},
    @{id='GM.MAP.CONSEQUENCES.CONDITIONAL'; math='Finite-spread approximation gives prime/primary/non-PFP and continuum many maximal ideals'; lean='ThesisCommon.GowersMaurey.shiftSpace_prime_of_finiteSpreadApproximation'; depends=@('GM.WIENER.QUOTIENT.CONDITIONAL','GM.HYPERPLANES','ThesisCommon.GowersMaurey.shiftSpace_continuum_le_maximalIdeals_of_finiteSpreadApproximation'); remaining_inputs=@('Every actual operator is finite-spread approximable')},
    @{id='GM.MAXIMAL.FINITERANK'; math='Every maximal operator ideal on the actual space contains all finite-rank operators'; lean='ThesisCommon.GowersMaurey.finiteRank_mem_maximalOperatorIdeal'; depends=@('GM.SS.IDEAL','ThesisCommon.finiteRank_mem_twoSidedIdeal_of_ne_bot'); remaining_inputs=@()},
    @{id='GM.LAURENT.BOUNDARY'; math='The actual unilateral Laurent range is not closed under multiplication'; lean='ThesisCommon.GowersMaurey.exists_laurent_product_not_laurent'; depends=@('ThesisCommon.GowersMaurey.completedSpread_right_left_ne_laurentOperator'); remaining_inputs=@()}
)
$graph += @(
    @{id='GM.SS.CONVERSE';math='Nonzero actual Laurent operators are not strictly singular; approximable operators have the exact strictly-singular kernel';lean='ThesisCommon.GowersMaurey.spaceOperatorSeminorm_zero_iff_strictlySingular_of_approximable';depends=@('ThesisCommon.GowersMaurey.not_strictlySingular_laurent_of_ne_zero','GM.KERNEL.SS');remaining_inputs=@('Finite-spread approximation for the particular operator')},
    @{id='GM.MAXIMAL.SS';math='Every actual maximal operator ideal contains all strictly singular operators';lean='ThesisCommon.GowersMaurey.allMaximalIdealsContainStrictlySingular';depends=@('GM.SS.IDEAL','ThesisCommon.GowersMaurey.strictlySingular_hasFiniteRankInvertibleCorrection_id_sub','ThesisCommon.finiteRankInvertibleCorrection_of_connected_family','ThesisCommon.exists_finiteRank_invertible_correction_of_mem_closure_units');remaining_inputs=@()},
    @{id='GM.CODED.RECURSION';math='Actual coded detecting families are simultaneously literal special sequences and outer RIS';lean='ThesisCommon.GowersMaurey.exists_detecting_special_RIS_family';depends=@('GM.CODED.NPAIRS','ThesisCommon.GowersMaurey.exists_detecting_special_family','ThesisCommon.GowersMaurey.CodedDetectingFamily.outerRIS');remaining_inputs=@()},
    @{id='GM.EXCEPTION.ENVELOPE';math='Original coded exceptional special tests are absorbed by a genuine affine norming bound';lean='ThesisCommon.GowersMaurey.exists_norming_form_of_affine_exception_bound';depends=@('ThesisCommon.GowersMaurey.implicitNorm_eq_oneExceptionFormNormEnvelope','ThesisCommon.GowersMaurey.spread_comp');remaining_inputs=@()},
    @{id='GM.FIXED.POINT';math='Actual compact finite operator orbit admits the Kakutani diagonal conclusion';lean='ThesisCommon.finite_operator_orbit_fixed_point';depends=@('ThesisCommon.compact_convex_operator_fixed_point','ThesisCommon.FixedPoint.kakutani_fixed_point','ThesisCommon.isCompact_finiteAbsoluteConvexOrbit');remaining_inputs=@()},
    @{id='GM.EXAMPLE.CONDITIONAL';math='All six original Example7.1 clauses follow from genuine finite-spread approximation';lean='PFP.example_7_1_of_finiteSpreadApproximation';depends=@('GM.MAXIMAL.SS','GM.SS.CONVERSE','ThesisCommon.GowersMaurey.hasStrictlySingularWienerQuotient_of_finiteSpreadApproximation','ThesisCommon.GowersMaurey.hasContinuumManyMaximalOperatorIdeals_of_finiteSpreadApproximation','GM.MAP.CONSEQUENCES.CONDITIONAL');remaining_inputs=@('Every actual operator is finite-spread approximable in the literal seminorm')},
    @{id='JT.ANTICHAIN';math='Actual antichain lp estimates prove weak nullity and small level images';lean='ThesisCommon.exists_jamesTree_subtree_small_level_image';depends=@('ThesisCommon.jamesTree_antichain_norm_finite','ThesisCommon.jamesTreeAntichainProjection_idempotent');remaining_inputs=@()},
    @{id='JT.SELECTED.BRANCHES';math='One of T and id-T has a genuine full subtree with nonzero branch coefficients and summable branch deviations';lean='ThesisCommon.exists_jamesTree_selected_branch_control';depends=@('ThesisCommon.exists_monochromatic_dyadic_subtree','ThesisCommon.exists_dyadic_subtree_small_oscillation');remaining_inputs=@()}
)
foreach ($node in $graph) {
    if ($node.id -in @('GM.TARGET','GM.WIENER','GM.WIENER.QUOTIENT.CONDITIONAL','GM.MAP.CONSEQUENCES.CONDITIONAL','GM.SS.CONVERSE','GM.EXAMPLE.CONDITIONAL','GM.CONDITIONAL.PRIME')) {
        $node.depends += @('GM.OPERATOR.APPROXIMATION')
        $node.remaining_inputs = @()
    }
    if ($node.id -eq 'GM.TARGET') { $node.math='All six original clauses proved on the actual named complex shift space'; $node.lean='PFP.example_7_1_named' }
}
$graph += @(
    @{id='GM.LEMMA8';math='Actual vectorwise finite-spread approximation on every actual subspace';lean='ThesisCommon.GowersMaurey.exists_vectorwise_spread_orbit_approximation';depends=@('GM.CODED.RECURSION','GM.EXCEPTION.ENVELOPE','ThesisCommon.GowersMaurey.CodedDetectingFamily.sum_norm_le','ThesisCommon.GowersMaurey.ConstructionData.exists_special_pair_lower_gt_upper');remaining_inputs=@()},
    @{id='GM.CONTINUOUS.SELECTOR';math='Actual jointly norming RIS averages and finite partitions give continuous bad vectors';lean='ThesisCommon.GowersMaurey.exists_simultaneous_bad_averages';depends=@('ThesisCommon.GowersMaurey.exists_norming_RIS_of_lt_seminorm','ThesisCommon.GowersMaurey.norm_combined_average_completedPairing_le_two','ThesisCommon.exists_finite_metric_partition');remaining_inputs=@()},
    @{id='GM.LEMMA9';math='Kakutani on the actual finite operator orbit gives genuine operator-seminorm approximation';lean='ThesisCommon.GowersMaurey.exists_operator_orbit_seminorm_approximation';depends=@('GM.LEMMA8','GM.CONTINUOUS.SELECTOR','ThesisCommon.finite_rectangular_operator_orbit_fixed_point');remaining_inputs=@()},
    @{id='GM.OPERATOR.APPROXIMATION';math='Every bounded operator is finite-spread approximable in the literal source seminorm';lean='ThesisCommon.GowersMaurey.finiteSpreadApproximable';depends=@('GM.LEMMA9');remaining_inputs=@()},
    @{id='GM.EXAMPLE.FULL';math='All original Example7.1 clauses and every actual admissible construction';lean='PFP.example_7_1_all_constructions';depends=@('GM.DATA','GM.OPERATOR.APPROXIMATION','GM.EXAMPLE.CONDITIONAL');remaining_inputs=@()},
    @{id='R5.2.COMPRESSION.OBSTRUCTION';math='Actual diagonal evaluation obstructs unrestricted local coefficient compression, without deciding unrestricted PFP transfer';lean='ThesisCommon.freeNatUltrafilter_diagonal_not_local_coefficient';depends=@('ThesisCommon.continuousFunctionDiagonal_not_local_coefficient','ThesisCommon.infinite_nat_set_exists_disjoint_infinite_subsets');remaining_inputs=@()},
    @{id='JT.SELECTED.COMPLEMENT';math='Actual norm-one selected insertion/readback and exact closed-span range';lean='ThesisCommon.jamesTreeSelectedProjection_range';depends=@('ThesisCommon.jamesTreeSelectedRead_comp_insert');remaining_inputs=@()},
    @{id='JT.COLUMN.PRUNING';math='Actual Andrew Proposition3 pruning for both segment conventions';lean='ThesisCommon.exists_consecutiveJamesTree_pruned_column';depends=@('ThesisCommon.jamesTree_disjoint_masks_sum_rpow_le','ThesisCommon.exists_literalJamesTree_pruned_column');remaining_inputs=@()},
    @{id='JT.RECIPROCAL';math='Genuine full-vector reciprocal multipliers stable after later subtree selection';lean='ThesisCommon.exists_consecutiveJamesTree_uniform_branch_inverse';depends=@('JT.SELECTED.BRANCHES');remaining_inputs=@()},
    @{id='JT.ERROR.ASSEMBLY';math='Summable actual unit-column errors give exact6 factors through delayed compression';lean='ThesisCommon.jamesTree_delayed_compression_factors_six';depends=@('ThesisCommon.norm_jamesTree_sub_le_of_summable_columns','ThesisCommon.factorsIdentityWith_six_of_near_compression_left_inverse');remaining_inputs=@('Actual recursive tree selection with the stated column errors')}
)
foreach ($node in $graph) {
    if ($node.id -in @('JT.BASIS','JT.ERROR.ASSEMBLY')) { $node.remaining_inputs = @() }
}
$graph += @(
    @{id='JT.FINITE.COLUMN.DICHOTOMY'; math='Actual operator-dependent frontier recursion discharges all column errors and gives factor bound six for both finite-column models'; lean='ThesisCommon.consecutiveJamesTree_finite_column_factor_dichotomy'; depends=@('JT.COLUMN.PRUNING','JT.RECIPROCAL','JT.ERROR.ASSEMBLY','ThesisCommon.literalJamesTree_finite_column_factor_dichotomy'); remaining_inputs=@()},
    @{id='JT.ALL.OPERATORS'; math='Genuine finite-column perturbation removes support assumptions and gives uniform twelve-PFP for both actual completions'; lean='ThesisCommon.consecutiveJamesTree_hasCPFP_twelve'; depends=@('JT.FINITE.COLUMN.DICHOTOMY','ThesisCommon.jamesTree_hasCPFP_twelve_of_finite_column_dichotomy','ThesisCommon.literalJamesTree_hasCPFP_twelve'); remaining_inputs=@()},
    @{id='JT.TARGET'; math='Both unchanged Theorem5.4 targets hold for every RCLike field and every finite p>1'; lean='PFP.theorem_5_4'; depends=@('JT.ALL.OPERATORS','PFP.theorem_5_4_asPrinted','PFP.theorem_5_4_consecutive'); remaining_inputs=@()},
    @{id='BM.APPROXIMATE.BOUND'; math='Closed infimum bound is equivalent to actual isomorphisms with every larger distortion bound'; lean='PFP.definition_2_1_approximate_bound'; depends=@('ThesisCommon.banachMazurDistance_le_iff_approximate_isomorphic_bound'); remaining_inputs=@()},
    @{id='COORDINATE.COUNTABLE.COUNTEREXAMPLES'; math='Actual rank-one countable c0 operator negates both unrestricted printed coordinate-selection lemmas'; lean='PFP.lemma_4_30_asPrinted_false_countable_cZero'; depends=@('PFP.lemma_4_27_asPrinted_false_countable_cZero'); remaining_inputs=@()}
)
$graph | ConvertTo-Json -Depth 10 | Set-Content -Encoding utf8 -LiteralPath (Join-Path $project 'proof-graph.json')

# Traverse every local import of the paper and both audits. Mathlib is pinned
# separately in the Lake manifest; local source hashes identify the checkpoint.
$queue = [System.Collections.Generic.Queue[string]]::new()
foreach ($module in @('PFP','PFP.Audit','ThesisCommon.PFPAudit','ThesisCommon.PFPAuditImports')) { $queue.Enqueue($module) }
$seen = [System.Collections.Generic.HashSet[string]]::new()
$hashes = [System.Collections.Generic.List[object]]::new()
$declarations = @{}
while ($queue.Count) {
    $module = $queue.Dequeue()
    if (!$seen.Add($module)) { continue }
    $relative = Resolve-LocalLeanModule $module
    if (!$relative) { continue }
    $path = Join-Path $formalRoot $relative
    $content = Get-Content -Raw -Encoding utf8 -LiteralPath $path
    $hashes.Add([ordered]@{path=$relative; sha256=(Get-FileHash -Algorithm SHA256 -LiteralPath $path).Hash})
    foreach ($match in [regex]::Matches($content,'(?m)^import ([A-Za-z0-9_.]+)')) { $queue.Enqueue($match.Groups[1].Value) }
    $matches = [regex]::Matches($content,'(?m)^(?:@\[[^\]\r\n]+\][ \t]+)*(?:theorem|def|abbrev|structure|instance) ([A-Za-z0-9_.]+)')
    foreach ($match in $matches) {
        $tail = $content.Substring($match.Index)
        $next = [regex]::Match($tail.Substring($match.Length),'(?m)^(?:/--|theorem |def |abbrev |structure |instance |end |include |@\[)')
        $excerpt = if ($next.Success) { $tail.Substring(0,$match.Length + $next.Index).TrimEnd() } else { $tail.TrimEnd() }
        $scopes = [System.Collections.Generic.List[string]]::new()
        foreach ($scope in [regex]::Matches($content.Substring(0,$match.Index),'(?m)^(?:namespace ([A-Za-z0-9_.]+)|(?:noncomputable )?section(?: [A-Za-z0-9_]+)?|end(?: [A-Za-z0-9_.]+)?)[ \t]*\r?$')) {
            if ($scope.Groups[1].Success) { $scopes.Add($scope.Groups[1].Value) }
            elseif ($scope.Value.StartsWith('end')) {
                if ($scopes.Count) { $scopes.RemoveAt($scopes.Count-1) }
            } else { $scopes.Add('') }
        }
        $ns = (@($scopes | Where-Object { $_ }) -join '.') + '.'
        $declarations[$ns+$match.Groups[1].Value] = [ordered]@{path=$relative; code=$excerpt}
    }
}

function Html([string]$text) { [System.Net.WebUtility]::HtmlEncode($text) }
$html = [System.Text.StringBuilder]::new()
[void]$html.AppendLine('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Primariness and the PFP — Lean companion</title><style>body{font:17px/1.55 system-ui;margin:40px auto;max-width:1450px;padding:0 22px;color:#18252d}h1,h2{line-height:1.2}.notice{padding:18px;background:#fff4ce;border-left:5px solid #b98000}.pair{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.2fr);gap:26px;margin:22px 0 48px}.pane{min-width:0}pre{font:13px/1.5 Consolas,monospace;white-space:pre-wrap;overflow-wrap:anywhere;background:#f0f4f6;padding:16px;border-radius:6px}summary{cursor:pointer}small{color:#52616b}a{color:#005f86}.status{font-weight:600}section{border-top:1px solid #d2dade;padding-top:22px}@media(max-width:850px){.pair{grid-template-columns:1fr}}@media print{body{font-size:11px;margin:12px}pre{font-size:8px}section{break-before:page}}</style><h1>Primariness and the Primary Factorisation Property</h1><p>Acuaviva–Kania · supplied manuscript · Lean 4.24.0 · 3 October 2026</p><p class="notice"><strong>Partial formalisation.</strong> The metadata records 77 complete original results, including both formulations of Theorem 5.4 and Example 7.1, both clauses of Corollary 4.10, Corollary 4.7 and Remarks 3.4, 4.5 and 4.31, the endpoint quotient result 5.1, the full matrix chain 5.6--5.15 and both original clauses of Appendix B.4, together with separately labelled corrected, context-restored and partial results. The verification link identifies the last successful combined checkpoint. Proposition 2.6 needs a nonzero-space hypothesis; its printed zero case is disproved. Remarks are optional by user instruction. The printed endpoint-attainment assertion in Definition 2.1 remains unproved; its correct all-epsilon formulation is checked. Source corrections and separately preserved original formulas are labelled below.</p><p><a href="STATUS.txt">Status and remaining work</a> · <a href="SOURCE_ISSUES.txt">Source issues</a> · <a href="verification/summary.json">Verification</a> · <a href="source-inventory.json">Complete inventory</a></p>')
foreach ($row in $rows) {
    [void]$html.AppendLine("<section><h2>$(Html $row.number) — $(Html $row.id)</h2><p class='status'>$(Html $row.proof_status)</p><small>$(Html $row.source):$($row.line)</small><div class='pair'><div class='pane'><h3>Ordinary mathematics</h3><p>$(Html $row.ordinary_mathematics)</p><p>$(Html $row.correspondence_notes)</p><details><summary>Original LaTeX statement</summary><pre>$(Html $row.original_statement)</pre></details></div><div class='pane'><h3>Checked Lean source</h3>")
    foreach ($name in $row.lean_declarations) {
        if (!$declarations.ContainsKey($name)) { throw "Missing checked declaration excerpt: $name" }
        $item = $declarations[$name]
        $link = '../' + $item.path
        [void]$html.AppendLine("<p><strong>$(Html $name)</strong> · <a href='$(Html $link)'>Full source</a></p><pre>$(Html $item.code)</pre>")
    }
    [void]$html.AppendLine('</div></div></section>')
}
[void]$html.AppendLine('<section><h2>Definitions behind the targets</h2><p>These are actual definitions from the compiled sources. A target returning Prop does not assert that its proposition holds.</p>')
foreach ($name in @('ThesisCommon.IsPrimary','ThesisCommon.FactorsIdentityWith','ThesisCommon.HasCPFP','ThesisCommon.HasCPlusPFP','ThesisCommon.HasUPFP','PFP.ScalarEllOne','PFP.MatrixBlock','PFP.MatrixSum','ThesisCommon.IsomorphicWithBound','PFP.HasUncountableCofinality')) {
    $item = $declarations[$name]
    if (!$item) { throw "Missing definition: $name" }
    [void]$html.AppendLine("<h3>$(Html $name)</h3><pre>$(Html $item.code)</pre>")
}
[void]$html.AppendLine('</section><p>Excerpts are regenerated from the compiled local sources. <a href="checked-source-hashes.json">SHA-256 source hashes</a> identify the exact checkpoint. No source sentence, citation, open target, or conditional interface is counted as a proof.</p></html>')
if ($PrepareMetadata) {
    $preparedHtml = $html.ToString().Replace('<h1>Primariness and the Primary Factorisation Property</h1>',
        '<h1>Primariness and the Primary Factorisation Property</h1><p class="notice"><strong>Combined verification pending.</strong> This metadata includes individually checked additions. The verification summary and checked-source hashes still identify the previous successful combined checkpoint.</p>')
    $preparedHtml = $preparedHtml.Replace('identify the exact checkpoint.', 'identify the previous successful combined checkpoint until verification completes.')
    $preparedHtml | Set-Content -Encoding utf8 -LiteralPath (Join-Path $project 'companion.html')
    Write-Output "Prepared metadata for $($hashes.Count) local Lean modules; checked hashes and verification summary unchanged."
} else {
    if ($VerifiedSourceSnapshot) {
        $checkedInputs = @(Get-Content -Raw -Encoding utf8 -LiteralPath $VerifiedSourceSnapshot | ConvertFrom-Json)
        # Catch edits during metadata generation, then publish the exact
        # hashes of the checked snapshot rather than newly observed sources.
        Assert-VerificationSnapshotFilesUnchanged $formalRoot $checkedInputs
        $checkedLean = @($checkedInputs | Where-Object kind -eq 'lean')
        Assert-VerificationSnapshotsEqual $checkedLean @($hashes | ForEach-Object {
            [ordered]@{kind='lean';path=$_.path;sha256=$_.sha256}
        })
        $hashes = @($checkedLean | ForEach-Object { [ordered]@{path=$_.path;sha256=$_.sha256} })
    }
    $html.ToString() | Set-Content -Encoding utf8 -LiteralPath (Join-Path $project 'companion.html')
    $hashes | Sort-Object path | ConvertTo-Json -Depth 8 | Set-Content -Encoding utf8 -LiteralPath (Join-Path $project 'checked-source-hashes.json')
    Write-Output "Updated correspondence, proof graph, companion, and hashes for $($hashes.Count) local Lean modules."
}















